sed'=>'Hết khung giờ'][$j['recent_status']]??$j['recent_status']):'Chưa có lượt chạy')?> · <?=e($formatTime($j['recent_started']??null))?></small><div class="actions end"><a class="button" href="?edit=<?=e($j['id'])?>#scheduleEditor">Sửa</a><?php foreach(['toggle'=>'Bật/tắt','manual'=>'Chạy thử','delete'=>'Bỏ lịch']as$a=>$l):?><form method="post" <?=$a==='delete'?'onsubmit="return confirm(\'Bỏ lịch này? Các file trên Drive vẫn được giữ.\')"':''?>><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="id" value="<?=e($j['id'])?>"><input type="hidden" name="action" value="<?=$a?>"><button class="<?=$a==='delete'?'danger':''?>"><?=$l?></button></form><?php endforeach;?></div></td></tr><?php endforeach;?><?php if(!$jobs):?><tr><td colspan="5" class="muted">Chưa có lịch. Có thể thêm tại đây hoặc bấm nút đồng hồ cạnh các nút xuất báo cáo trên các trang.</td></tr><?php endif;?></tbody></table></div></section>
<details class="card"><summary>Lịch sử chạy gần nhất (lưu 90 ngày)</summary><div class="table-wrap"><table><thead><tr><th>Lịch</th><th>Bắt đầu</th><th>Kết quả</th><th>Thông tin</th></tr></thead><tbody><?php foreach($history as$h):?><tr><td><?=e($h['name']??'Lịch đã bỏ')?></td><td class="nowrap"><?=e($formatTime($h['started_at']))?></td><td><span class="pill <?=e($h['status'])?>"><?=e(['success'=>'Thành công','failed'=>'Chưa thành công','running'=>'Đang chạy','missed'=>'Hết khung giờ'][$h['status']]??$h['status'])?></span><br><small>Lượt <?=(int)$h['attempts']?></small></td><td><?=e($h['message'])?><?php if($h['status']==='success'&&$h['remote_file_id']):?> <a target="_blank" rel="noopener" href="https://drive.google.com/file/d/<?=rawurlencode($h['remote_file_id'])?>/view">Mở file</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></details>
<details class="card" <?=empty($state['last_tick_at'])?'open':''?>><summary>Cài chạy nền một lần trên hosting</summary><p>Thêm dòng sau vào Cron Jobs của hosting. Chọn PHP CLI phù hợp (8.2/8.3); chạy mỗi 5 phút. Cron tự kiểm tra khung giờ Việt Nam, không cần mở website. Khởi tạo schema và kết nối Drive trước khi bật.</p><code><?=e($cron)?></code><p class="muted">Mỗi lượt xử lý tuần tự tối đa 10 lịch; không chạy trùng. Khung 00:00–05:00 nghĩa là hệ thống phân bổ lượt chạy trong khoảng này, không dồn mọi báo cáo lúc 00:00. Lỗi tự thử lại tối đa 3 lần trong khung giờ. “Chạy thử” là yêu cầu rõ ràng để cron chạy ở lượt tới, kể cả ban ngày.</p><a href="https://github.com/nguyenhongdanxm/cds/blob/main/docs/EXCEL_DRIVE_SCHEDULES.md" target="_blank" rel="noopener">Hướng dẫn chi tiết</a></details>
</main><script>
const catalog=<?=json_encode($catalog,JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,labels=<?=json_encode(array_combine(array_unique(array_merge(...array_column($catalog,'fields'))),array_map('xlsched_field_label',array_unique(array_merge(...array_column($catalog,'fields'))))),JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP)?>;
let current=<?=json_encode(json_decode($form['params_json'],true)?:[],JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,savedPolicy=<?=json_encode($form['date_policy'])?>;
const options={fixed:'Giữ bộ lọc đã chọn',yesterday:'Hôm qua',today:'Ngày chạy',month:'Tháng đang chạy',previous_month:'Tháng trước',week:'Tuần đang chạy',previous_week:'Tuần trước'};
function render(){const report=catalog[document.getElementById('reportSelect').value],holder=document.getElementById('filterFields');holder.replaceChildren();for(const key of report.fields){const wrap=document.createElement('div'),label=document.createElement('label'),array=['ids','fields','export_week_ids'].includes(key),input=document.createElement(array?'textarea':(['collection','extension'].includes(key)?'select':'input'));if(key==='collection'||key==='extension'){const choices=key==='collection'?{all:'Tất cả tệp Word/PDF tải lên',documents:'Văn bản',academic:'Chuyên môn'}:{all:'Word và PDF',pdf:'Chỉ PDF',doc:'Word DOC',docx:'Word DOCX'};for(const[value,text]of Object.entries(choices)){const o=document.createElement('option');o.value=value;o.textContent=text;input.append(o);}}label.textContent=labels[key]||key;input.name='filters['+key+']';input.value=Array.isArray(current[key])?current[key].join('\n'):(current[key]||(['collection','extension'].includes(key)?'all':''));if(array)input.rows=2;else if(/^(from|to|date|stats_from|stats_to|health_from|health_to)$/.test(key))input.type='date';else if(/month$/.test(key))input.type='month';wrap.append(label,input);holder.append(wrap);}const policy=document.getElementById('datePolicy');policy.replaceChildren();for(const[key,label]of Object.entries(options)){if(key!=='fixed'&&(!Object.keys(report.date).length||(report.policies&&!report.policies.includes(key))))continue;const o=document.createElement('option');o.value=key;o.textContent=label;policy.append(o);}policy.value=[...policy.options].some(o=>o.value===savedPolicy)?savedPolicy:'fixed';document.getElementById('filterDetails').hidden=!report.fields.length;}
function updateSource(){const report=catalog[document.getElementById('reportSelect').value],link=document.getElementById('sourceExportLink');document.getElementById('sourcePath').textContent=report.path;document.getElementById('sourceType').textContent='Đầu ra: '+report.format.toUpperCase()+(report.format==='zip'?(report.id==='original_pdf'?' (chứa PDF gốc)':report.file_group==='word'?' (chứa Word)':' (gói tài liệu)'):'')+' · '+report.method;const url=new URL(report.path,new URL('.',location.href));for(const[key,value]of Object.entries(report.fixed))url.searchParams.set(key,value);const fields=new FormData(document.getElementById('scheduleForm')),values={};for(const key of report.fields){const value=fields.get('filters['+key+']');if(!value)continue;if(['ids','fields','export_week_ids'].includes(key)){values[key]=String(value).split(/\r?\n/).map(x=>x.trim()).filter(Boolean);for(const item of values[key])url.searchParams.append(key+'[]',item);}else{values[key]=String(value);url.searchParams.set(key,value);}}const missing=(report.required||[]).some(key=>!values[key]||Array.isArray(values[key])&&!values[key].length);const dynamic=fields.get('date_policy')!=='fixed';document.getElementById('sourceHint').textContent=dynamic?'Kỳ dữ liệu được xác định khi cron chạy. Chọn Giữ bộ lọc và điền đủ ngày/tuần để xem trước.':missing?'Chọn đủ bộ lọc bắt buộc để mở đúng tệp xuất.':report.method!=='GET'?'Nguồn này xuất bằng biểu mẫu ở trang gốc.':'';link.hidden=report.method!=='GET'||missing||dynamic||url.href.length>12000;if(!link.hidden)link.href=url.href;else link.removeAttribute('href');}
function filterFileTypes(){const type=document.getElementById('fileTypeFilter').value,select=document.getElementById('reportSelect');for(const option of select.options){const match=type==='all'||catalog[option.value].file_group===type;option.hidden=!match;option.disabled=!match;}if(select.selectedOptions[0]?.disabled){select.value=[...select.options].find(o=>!o.disabled)?.value||'';select.dispatchEvent(new Event('change'));}updateSource();}
document.getElementById('jobTypeFilter').addEventListener('change',event=>{for(const row of document.querySelectorAll('[data-file-group]'))row.hidden=event.target.value!=='all'&&row.dataset.fileGroup!==event.target.value;});
document.getElementById('fileTypeFilter').addEventListener('change',filterFileTypes);document.getElementById('scheduleForm').addEventListener('input',updateSource);document.getElementById('scheduleForm').addEventListener('change',updateSource);
document.getElementById('reportSelect').addEventListener('change',()=>{current={};savedPolicy='fixed';document.getElementById('jobName').value=catalog[document.getElementById('reportSelect').value].label;render();updateSource();});document.getElementById('frequency').addEventListener('change',()=>{const frequency=document.getElementById('frequency').value,holder=document.getElementById('dayField'),value=<?=(int)$form['day']?>;holder.hidden=frequency==='daily';holder.replaceChildren();if(holder.hidden)return;const label=document.createElement('label'),input=document.createElement(frequency==='weekly'?'select':'input');label.textContent=frequency==='weekly'?'Ngày trong tuần':'Ngày trong tháng (tháng ngắn lấy ngày cuối)';input.name='day';if(frequency==='weekly'){['Thứ Hai','Thứ Ba','Thứ Tư','Thứ Năm','Thứ Sáu','Thứ Bảy','Chủ nhật'].forEach((day,index)=>{const option=document.createElement('option');option.value=index+1;option.textContent=day;input.append(option);});input.value=Math.min(value,7);}else{input.type='number';input.min='1';input.max='31';input.value=value;}holder.append(label,input);});document.getElementById('frequency').dispatchEvent(new Event('change'));render();filterFileTypes();updateSource();
</script></body></html>
